begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
update public.community_operations set enabled=true,enrollment=true,discovery=true,publish=true,engagement=true,cohort_required=false;
create function pg_temp.routine_fixture_receipt() returns trigger language plpgsql as $$begin new.terms_version:='2026-09-30';new.terms_accepted_at:=now();new.adult_declared_at:=now();return new;end $$;
create trigger community_routine_fixture_receipt before insert on public.community_profiles for each row execute function pg_temp.routine_fixture_receipt();
insert into auth.users(id,email) select ('c1610000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'comm161-'||i||'@mizyun.test' from generate_series(1,4)i;
update public.profiles set birth_year=extract(year from now())::integer-30 where id::text like 'c1610000%';
insert into public.community_profiles(user_id,handle,display_name,status) select id,'comm161_'||right(id::text,12),'Synthetic member','active' from auth.users where id::text like 'c1610000%';
insert into public.community_relationships(follower_user_id,target_user_id,status) values('c1610000-0000-4000-8000-000000000002','c1610000-0000-4000-8000-000000000001','approved');
insert into public.workouts(id,user_id,name,started_at,notes,details) values('a1610000-0000-4000-8000-000000000001','c1610000-0000-4000-8000-000000000001','PRIVATE TITLE',now(),'PRIVATE HEALTH NOTE','{"workoutLifecycle":{"kind":"routine"},"injury":"PRIVATE","coachPlan":{"health":"PRIVATE","exercises":[{"name":"Bench press","targetSets":3,"targetReps":"8-12","targetLoad":"100 lb","restSeconds":90,"notes":"PRIVATE NOTE","catalogId":"foreign-id"}]}}');
create temp table routine_state(key text primary key,value jsonb);
grant all on routine_state to authenticated;
set local role authenticated;
set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='c1610000-0000-4000-8000-000000000001';
select throws_ok($$select public.community_routines('preview','{"sourceWorkoutId":"a1610000-0000-4000-8000-000000000001","title":"Strength"}')$$,'P0001','community_unavailable','Default disabled feature denies source preview');
reset role;
update public.community_feature_controls set enabled=true where feature='routines';
set local role authenticated;
insert into routine_state values('preview',public.community_routines('preview','{"sourceWorkoutId":"a1610000-0000-4000-8000-000000000001","title":"Strength"}'));
select is((select value->'snapshot'->'exercises'->0->>'loadKg' from routine_state where key='preview'),'45.359','Server converts pounds deterministically');
select ok((select value::text not like '%PRIVATE%' and value::text not like '%foreign-id%' from routine_state where key='preview'),'Preview excludes title notes health and source references');
select throws_ok($$select public.community_routines('publish',jsonb_build_object('sourceWorkoutId','a1610000-0000-4000-8000-000000000001','operationId','e1610000-0000-4000-8000-000000000001','sourceUpdatedAt',(select value->>'sourceUpdatedAt' from routine_state where key='preview'),'confirmed',false,'snapshot',(select value->'snapshot' from routine_state where key='preview')))$$,'P0001','community_invalid_input','Confirmation required');
select throws_ok($$select public.community_routines('publish',jsonb_build_object('sourceWorkoutId','a1610000-0000-4000-8000-000000000001','operationId','e1610000-0000-4000-8000-000000000001','sourceUpdatedAt',(select value->>'sourceUpdatedAt' from routine_state where key='preview'),'confirmed',true,'snapshot',(select value->'snapshot'||'{"private":"forged"}'::jsonb from routine_state where key='preview')))$$,'P0001','community_conflict','Forged fields rejected at real publication boundary');
insert into routine_state values('share',public.community_routines('publish',jsonb_build_object('sourceWorkoutId','a1610000-0000-4000-8000-000000000001','operationId','e1610000-0000-4000-8000-000000000001','sourceUpdatedAt',(select value->>'sourceUpdatedAt' from routine_state where key='preview'),'confirmed',true,'snapshot',(select value->'snapshot' from routine_state where key='preview'))));
select is((public.community_routines('publish',jsonb_build_object('sourceWorkoutId','a1610000-0000-4000-8000-000000000001','operationId','e1610000-0000-4000-8000-000000000001','sourceUpdatedAt',(select value->>'sourceUpdatedAt' from routine_state where key='preview'),'confirmed',true,'snapshot',(select value->'snapshot' from routine_state where key='preview')))->>'id'),(select value->>'id' from routine_state where key='share'),'Lost publication response creates no duplicate');
select throws_ok($$select * from public.community_routine_shares$$,'42501',null,'Raw table cannot expose source workout ID');
select throws_ok($$select * from public.community_routine_imports$$,'42501',null,'Raw import attribution requires owner export RPC');
set local request.jwt.claim.sub='c1610000-0000-4000-8000-000000000003';
select throws_ok($$select public.community_routines('get',jsonb_build_object('id',(select value->>'id' from routine_state where key='share')))$$,'P0001','community_unavailable','Unrelated viewer denied guessed share');
set local request.jwt.claim.sub='c1610000-0000-4000-8000-000000000002';
select is((public.community_routines('get',jsonb_build_object('id',(select value->>'id' from routine_state where key='share')))->>'authorHandle'),'comm161_000000000001','Only approved follower gets safe authorship');
select throws_ok($$select public.community_routines('import',jsonb_build_object('id',(select value->>'id' from routine_state where key='share'),'version',1,'confirmed',false))$$,'P0001','community_invalid_input','Recipient import requires confirmation');
insert into routine_state values('copy',public.community_routines('import',jsonb_build_object('id',(select value->>'id' from routine_state where key='share'),'version',1,'confirmed',true)));
select is((public.community_routines('import',jsonb_build_object('id',(select value->>'id' from routine_state where key='share'),'version',1,'confirmed',true))->>'alreadyImported'),'true','Lost import response returns existing copy');
select is((select count(*) from public.workouts where id=(select (value->>'workoutId')::uuid from routine_state where key='copy')),1::bigint,'Exactly one independently owned private routine');
select ok((select notes is null and details::text not like '%PRIVATE%' and details::text not like '%foreign-id%' and details->'communityAttribution'->>'independentCopy'='true' from public.workouts where id=(select (value->>'workoutId')::uuid from routine_state where key='copy')),'Copy has safe targets and honest independent provenance');
update public.workouts set name='My edited independent routine' where id=(select (value->>'workoutId')::uuid from routine_state where key='copy');
select is((select count(*) from public.community_routine_export('routineShares',null,500)),0::bigint,'Recipient export excludes author shares');
select is((select count(*) from public.community_routine_export('routineImports',null,500)),1::bigint,'Recipient exports their import receipt');
insert into routine_state values('reportReceipt',jsonb_build_object('id',(select id from public.community_issue_report_receipt('routine',(select value->>'id' from routine_state where key='share')))));
select is((select id from public.community_issue_report_receipt('routine',(select value->>'id' from routine_state where key='share'))),(select (value->>'id')::uuid from routine_state where key='reportReceipt'),'Repeated explicit routine receipt returns the same unexpired evidence ID');
reset role;
select is((select name from public.workouts where id='a1610000-0000-4000-8000-000000000001'),'PRIVATE TITLE','Editing copied workout never writes back');
-- A source edit revokes current discovery/read/import; existing private copy survives.
update public.workouts set details=jsonb_set(details,'{coachPlan,exercises,0,targetReps}','"9-12"'::jsonb),notes='EDITED PRIVATE NOTE' where id='a1610000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.community_routines('get',jsonb_build_object('id',(select value->>'id' from routine_state where key='share')))$$,'P0001','community_unavailable','Source edit immediately invalidates shared snapshot');
select is((public.community_routines('import',jsonb_build_object('id',(select value->>'id' from routine_state where key='share'),'version',1,'confirmed',true))->>'alreadyImported'),'true','Retry after source edit returns only existing recipient copy');
select lives_ok($$select * from public.community_submit_report('routine',(select value->>'id' from routine_state where key='share'),'unsafe_or_sexual_content',null,(select (value->>'id')::uuid from routine_state where key='reportReceipt'))$$,'Report receipt retains evidence after source edit');
set local request.jwt.claim.sub='c1610000-0000-4000-8000-000000000003';
select throws_ok($$select public.community_routines('import',jsonb_build_object('id',(select value->>'id' from routine_state where key='share'),'version',1,'confirmed',true))$$,'P0001','community_unavailable','No new copy of stale source');
set local request.jwt.claim.sub='c1610000-0000-4000-8000-000000000001';
select is(jsonb_array_length(public.community_routines('list','{"mine":"true"}')->'items'),1,'Owner can manage stale publication without widening its audience');
-- Fresh generation must not revive a previously published audience consent.
insert into routine_state values('rejoinPreview',public.community_routines('preview','{"sourceWorkoutId":"a1610000-0000-4000-8000-000000000001","title":"Rejoin guard"}'));
insert into routine_state values('rejoinShare',public.community_routines('publish',jsonb_build_object('sourceWorkoutId','a1610000-0000-4000-8000-000000000001','operationId','e1610000-0000-4000-8000-000000000002','sourceUpdatedAt',(select value->>'sourceUpdatedAt' from routine_state where key='rejoinPreview'),'confirmed',true,'snapshot',(select value->'snapshot' from routine_state where key='rejoinPreview'))));
reset role;
set local request.jwt.claim.role='service_role';
update public.community_profiles set generation=generation+1 where user_id='c1610000-0000-4000-8000-000000000001';
set local role authenticated;
set local request.jwt.claim.role='authenticated';
set local request.jwt.claim.sub='c1610000-0000-4000-8000-000000000002';
select throws_ok($$select public.community_routines('get',jsonb_build_object('id',(select value->>'id' from routine_state where key='rejoinShare')))$$,'P0001','community_unavailable','Re-enrollment generation cannot resurrect an old published snapshot');
set local request.jwt.claim.sub='c1610000-0000-4000-8000-000000000001';
reset role;
update public.community_feature_controls set enabled=false where feature='routines';
set local role authenticated;
select is(jsonb_array_length(public.community_routines('list','{"mine":"true"}')->'items'),2,'Authenticated owner can manage own shares during feature freeze');
select lives_ok($$select public.community_routines('unshare',jsonb_build_object('id',(select value->>'id' from routine_state where key='share')))$$,'Privacy reduction survives global feature freeze');
reset role;
delete from public.workouts where id='a1610000-0000-4000-8000-000000000001';
set local role authenticated;
set local request.jwt.claim.sub='c1610000-0000-4000-8000-000000000002';
select is((select name from public.workouts where id=(select (value->>'workoutId')::uuid from routine_state where key='copy')),'My edited independent routine','Source removal preserves editable recipient copy');
select is((select count(*) from public.community_routine_export('routineImports',null,500)),1::bigint,'Import provenance remains after source removal');
select * from finish();
rollback;
